'use strict';
const $=s=>document.querySelector(s), size=10;
let questions=[],page=0,visible=[],shown=new Set(),picks={},lastFocus=null;
let state={saved:[],reviewed:[]};try{state={...state,...JSON.parse(localStorage.getItem('db-study-v1')||'{}')}}catch{}
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem('db-study-v1',JSON.stringify(state))}catch{}updateProgress()}
function updateProgress(){$('#progress').textContent=`${state.reviewed.length} / ${questions.length}`;$('#progressbar').value=state.reviewed.length}
function filter(){const term=$('#search').value.trim().toLowerCase(),topic=$('#topic').value,f=$('#filter').value;visible=questions.filter(q=>(!topic||q.gpt.topic===topic)&&(!term||`${q.id} ${q.text} ${q.choices.map(x=>x.text).join(' ')} ${q.gpt.body} ${q.discussion.map(x=>x.body).join(' ')}`.toLowerCase().includes(term))&&(f==='all'||f==='saved'&&state.saved.includes(q.id)||f==='reviewed'&&state.reviewed.includes(q.id)||f==='unread'&&!state.reviewed.includes(q.id)));page=0;render()}
function render(){const pages=Math.ceil(visible.length/size);page=Math.max(0,Math.min(page,pages-1));$('#count').textContent=`${visible.length} questions · ${questions.length} in collection`;$('#page').textContent=pages?`Page ${page+1} of ${pages}`:'No matches';$('#prev').disabled=page===0;$('#next').disabled=page>=pages-1;$('#questions').innerHTML=visible.slice(page*size,page*size+size).map(q=>{const reveal=shown.has(q.id);return `<article class="question" id="q${q.id}"><div class="question-header"><strong>Question #${q.id} <span style="font-weight:400">(Topic: Exam A)</span></strong><em>${esc(q.gpt.topic)}</em></div><div class="question-content"><div class="prompt">${q.html}</div><ul class="options">${q.choices.map(c=>`<li><button class="option ${picks[q.id]===c.letter?'picked':''} ${reveal&&q.answer.includes(c.letter)?'correct':''} ${reveal&&picks[q.id]===c.letter&&!q.answer.includes(c.letter)?'wrong':''}" data-action="pick" data-id="${q.id}" data-letter="${c.letter}" aria-pressed="${picks[q.id]===c.letter}"><span class="letter">${c.letter}.</span><div>${c.html}${reveal&&q.votes.some(v=>v.answer===c.letter&&v.percent===Math.max(...q.votes.map(v=>v.percent)))?'<span class="badge">Most Voted</span>':''}</div></button></li>`).join('')}</ul><div class="actions"><button data-action="reveal" data-id="${q.id}" aria-expanded="${reveal}">${reveal?'Hide':'Reveal'} Solution</button><button class="discuss" data-action="discuss" data-id="${q.id}">☁ Discussion <span class="badge" style="background:white;color:#536475">${q.discussion.length+1}</span></button><button class="bookmark ${state.saved.includes(q.id)?'on':''}" data-action="saved" data-id="${q.id}" aria-pressed="${state.saved.includes(q.id)}">${state.saved.includes(q.id)?'★ Saved':'☆ Bookmark'}</button><button class="review ${state.reviewed.includes(q.id)?'on':''}" data-action="reviewed" data-id="${q.id}" aria-pressed="${state.reviewed.includes(q.id)}">${state.reviewed.includes(q.id)?'✓ Reviewed':'Mark reviewed'}</button></div>${reveal?`<div class="solution"><div class="solution-top"><strong>Correct Answer: &nbsp; ${esc(q.answer)}</strong><span>Community vote ${q.votes.length?'supports Answer '+esc(q.votes[0].answer):'not available in archive'}</span></div><strong>Community vote distribution</strong><div class="votes">${q.votes.map(v=>`<div class="vote-row"><strong>${esc(v.answer)}</strong><div class="vote-track"><div class="vote-bar" style="width:${Number(v.percent)}%" title="${Number(v.votes)} votes">${Number(v.percent)}%</div></div></div>`).join('')}</div><p>Archived answers and community votes may differ. Read the discussion and compare the reasoning.</p></div>`:''}</div></article>`}).join('')||'<div class="empty">No questions match these filters.</div>';updateProgress()}
function linkify(text){return esc(text).replace(/https?:\/\/[^\s&lt;&gt;]+/g,url=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${url}</a>`)}
function discuss(q){lastFocus=document.activeElement;$('#discussion-title').textContent=`Exam Certified Data Engineer Associate · Question ${q.id} discussion`;$('#comments').innerHTML=`<article class="comment gpt"><div class="comment-header"><span class="avatar">G</span><strong>GPT</strong><span class="tag">Quick study note</span></div><div class="comment-body">${esc(q.gpt.body)}</div><a href="${esc(q.gpt.source)}" target="_blank" rel="noopener noreferrer">↗ Official reference</a></article>`+q.discussion.map(c=>`<article class="comment"><div class="comment-header"><span class="avatar">${esc(c.user.slice(0,1).toUpperCase())}</span><strong>${esc(c.user)}</strong><time>${esc(c.age)}</time></div>${c.selected?`<div class="selected">Selected Answer: ${esc(c.selected)}</div>`:''}<div class="comment-body">${linkify(c.body)}</div><small style="display:block;color:#8494a4;margin-top:8px">👍 upvoted ${Number(c.upvotes)} ${c.upvotes===1?'time':'times'}</small></article>`).join('')+(!q.discussion.length?'<p class="empty">No explanatory community comments in the supplied archive.</p>':'');$('#discussion').showModal();$('#discussion').scrollTop=0;$('#comments').scrollTop=0}
$('#questions').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const id=Number(b.dataset.id),q=questions.find(x=>x.id===id);switch(b.dataset.action){case'pick':picks[id]=b.dataset.letter;break;case'reveal':shown.has(id)?shown.delete(id):shown.add(id);break;case'discuss':discuss(q);return;default:{const key=b.dataset.action;state[key]=state[key].includes(id)?state[key].filter(x=>x!==id):[...state[key],id];save();if($('#filter').value!=='all'){filter();return}}}render();const target=document.querySelector(`[data-action="${b.dataset.action}"][data-id="${id}"]${b.dataset.letter?`[data-letter="${b.dataset.letter}"]`:''}`);target?.focus({preventScroll:true})});
$('#close').onclick=()=>$('#discussion').close();$('#discussion').addEventListener('close',()=>lastFocus?.focus({preventScroll:true}));$('#discussion').addEventListener('click',e=>{if(e.target===$('#discussion')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#search').addEventListener('input',filter);$('#topic').onchange=filter;$('#filter').onchange=filter;
for(const [id,delta]of[['prev',-1],['next',1]])$('#'+id).onclick=()=>{page+=delta;render();window.scrollTo({top:0,behavior:'smooth'})};
function jump(id){if(!questions.some(q=>q.id===id))return;$('#search').value='';$('#topic').value='';$('#filter').value='all';visible=questions.slice();page=Math.floor((id-1)/size);render();location.hash=`q${id}`;document.getElementById(`q${id}`)?.scrollIntoView({behavior:'smooth',block:'start'})}
$('#jump').addEventListener('keydown',e=>{if(e.key==='Enter')jump(Number(e.target.value))});
document.addEventListener('click',e=>{if(e.target.tagName!=='IMG')return;const d=document.createElement('dialog');d.className='image-dialog';d.innerHTML=`<button>Close image ×</button><img src="${esc(e.target.src)}" alt="Enlarged question diagram">`;document.body.append(d);d.querySelector('button').onclick=()=>d.close();d.addEventListener('close',()=>d.remove());d.showModal()});
fetch('data.json').then(r=>{if(!r.ok)throw Error(r.status);return r.json()}).then(data=>{questions=data;for(const topic of [...new Set(data.map(q=>q.gpt.topic))].sort()){$('#topic').add(new Option(topic,topic))}filter();const id=Number(location.hash.slice(2));if(id)jump(id)}).catch(()=>{$('#count').textContent='Questions could not load.';$('#questions').innerHTML='<div class="empty">Please refresh this page. For local viewing, serve this folder with an HTTP server.</div>'});

